44: /**
45:  * Exact age on a local calendar date (US-01 G1/G2, US-02 §2.2).
46:  * A 29-Feb birthday is considered to occur on 28-Feb in a non-leap year.
47:  * Returns `null` for future, impossible, malformed or pre-1900 dates.
48:  */
49: export function ageOnDate(birthDateIso: string, today: Date): number | null {
50:   const birthDate = parseIsoDate(birthDateIso);
51:   if (!birthDate) {
52:     return null;
53:   }
54: 
55:   const localToday = new Date(today.getFullYear(), today.getMonth(), today.getDate());
56:   if (birthDate > localToday) {
57:     return null;
58:   }
59: 
60:   const currentYear = localToday.getFullYear();
61:   let anniversaryDay = birthDate.getDate();
62:   if (birthDate.getMonth() === 1 && anniversaryDay === 29 && !isLeapYear(currentYear)) {
63:     anniversaryDay = 28;
64:   }
65:   const anniversary = new Date(currentYear, birthDate.getMonth(), anniversaryDay);
66: 
67:   const age = currentYear - birthDate.getFullYear() - (localToday < anniversary ? 1 : 0);
68:   return age < 0 ? null : age;
69: }
