77: /** Strips separators and normalises a Chilean RUT to `12345678-9`. */
78: export function normalizeClRut(value: string): string {
79:   const cleaned = value.replace(/[.\s-]/g, '').toUpperCase();
80:   const match = /^(\d{7,8})([0-9K])$/.exec(cleaned);
81:   return match ? `${match[1]}-${match[2]}` : cleaned;
82: }
