84: /** Strict módulo-11 check digit; accepts dotted, dashed or bare RUTs. */
85: export function isValidClRut(value: string): boolean {
86:   const cleaned = value.replace(/[.\s-]/g, '').toUpperCase();
87:   const match = /^(\d{7,8})([0-9K])$/.exec(cleaned);
88:   if (!match) {
89:     return false;
90:   }
91: 
92:   const body = match[1];
93:   const checkDigit = match[2];
94:   let sum = 0;
95:   let multiplier = 2;
96:   for (let index = body.length - 1; index >= 0; index -= 1) {
97:     sum += Number(body.charAt(index)) * multiplier;
98:     multiplier = multiplier === 7 ? 2 : multiplier + 1;
99:   }
100: 
101:   const remainder = 11 - (sum % 11);
102:   const expected = remainder === 11 ? '0' : remainder === 10 ? 'K' : String(remainder);
103:   return checkDigit === expected;
104: }
