2: 
3: import type {
4:   CountryCode,
5:   FormValue,
6:   PersistedWizardStateV1,
7:   WizardPersistence,
8:   WizardStep,
9: } from '../models';
10: import { STORAGE_PORT } from './storage.port';
11: 
12: export const DRAFT_TTL_MS = 2 * 60 * 60 * 1000;
13: 
14: export function wizardStorageKey(country: CountryCode): string {
15:   return `wizard:state:v1:${country}`;
16: }
17: 
18: const STEPS: readonly WizardStep[] = ['policyholder', 'plans', 'summary'];
19: 
20: @Injectable({ providedIn: 'root' })
21: export class WizardPersistenceService implements WizardPersistence {
22:   private readonly storage = inject(STORAGE_PORT);
23: 
24:   load(country: CountryCode): PersistedWizardStateV1 | null {
25:     const key = wizardStorageKey(country);
26:     try {
27:       const raw = this.storage.getItem(key);
28:       if (!raw) {
29:         return null;
30:       }
31: 
32:       const parsed: unknown = JSON.parse(raw);
33:       if (!isPersistedState(parsed) || parsed.schemaVersion !== 1 || parsed.country !== country) {
34:         this.discard(key, 'schema version or country mismatch');
35:         return null;
36:       }
37: 
38:       const savedAt = Date.parse(parsed.savedAt);
39:       if (!Number.isFinite(savedAt) || savedAt > Date.now() || Date.now() - savedAt > DRAFT_TTL_MS) {
40:         this.discard(key, 'expired or invalid savedAt');
41:         return null;
42:       }
43: 
44:       return parsed;
45:     } catch {
46:       this.warn('unavailable or corrupt storage');
47:       return null;
48:     }
49:   }
50: 
51:   save(state: PersistedWizardStateV1): void {
52:     try {
53:       this.storage.setItem(wizardStorageKey(state.country), JSON.stringify(state));
54:     } catch {
55:       this.warn('could not persist draft');
56:     }
57:   }
58: 
59:   clear(country: CountryCode): void {
60:     try {
61:       this.storage.removeItem(wizardStorageKey(country));
62:     } catch {
63:       this.warn('could not clear draft');
64:     }
65:   }
66: 
67:   private discard(key: string, reason: string): void {
68:     try {
69:       this.storage.removeItem(key);
70:     } catch {
71:       this.warn('could not discard draft');
72:     }
73:     this.warn(reason);
74:   }
75: 
76:   private warn(reason: string): void {
77:     if (isDevMode()) {
78:       console.warn(`[persistence] ${reason}.`);
79:     }
80:   }
81: }
82: 
83: function isPersistedState(value: unknown): value is PersistedWizardStateV1 {
84:   if (!isRecord(value)) {
85:     return false;
86:   }
87:   const step1 = value['step1'];
88:   if (!isRecord(step1)) {
89:     return false;
90:   }
91:   for (const key of Object.keys(step1)) {
92:     if (!isFormValue(step1[key])) {
93:       return false;
94:     }
95:   }
96: 
97:   return (
98:     value['schemaVersion'] === 1 &&
99:     (value['country'] === 'CO' || value['country'] === 'CL') &&
100:     typeof value['savedAt'] === 'string' &&
101:     typeof value['step'] === 'string' &&
102:     STEPS.includes(value['step'] as WizardStep) &&
103:     (value['selectedPlanDocumentId'] === null ||
104:       typeof value['selectedPlanDocumentId'] === 'string')
105:   );
106: }
107: 
108: function isFormValue(value: unknown): value is FormValue {
109:   return value === null || typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean';
110: }
111: 
112: function isRecord(value: unknown): value is Record<string, unknown> {
113:   return typeof value === 'object' && value !== null && !Array.isArray(value);
114: }

