19:   private readonly routeContext = signal<RouteContext>(this.readFromRouter());
20: 
21:   readonly country = computed<CountryCode>(() => this.routeContext().country);
22:   readonly currentStep = computed<WizardStep>(() => this.routeContext().step);
23:   readonly entry = computed(() => COUNTRY_CATALOG_BY_CODE[this.country()]);
24:   readonly locale = computed<AppLocale>(() => this.entry().locale);
25:   readonly currency = computed<CurrencyCode>(() => this.entry().currency);
26: 
27:   constructor() {
28:     this.router.events
29:       .pipe(
30:         filter((event): event is NavigationEnd => event instanceof NavigationEnd),
31:         takeUntilDestroyed(),
32:       )
33:       .subscribe(() => this.routeContext.set(this.readFromRouter()));
34:   }
35: 
36:   /** Single place where internal wizard links are built (ADR-001 §4.2). */
37:   quotePath(step: 'quote' | 'plans' | 'summary' = 'quote'): string {
38:     const segment = this.entry().routeSegment;
39:     return this.buildPath(segment, step);
40:   }
41: 
42:   pathFor(country: CountryCode, step: 'quote' | 'plans' | 'summary' = 'quote'): string {
43:     return this.buildPath(COUNTRY_CATALOG_BY_CODE[country].routeSegment, step);
44:   }
45: 
46:   private buildPath(segment: CountryRouteSegment, step: 'quote' | 'plans' | 'summary'): string {
47:     const suffix = step === 'quote' ? '' : `/${step}`;
48:     return `/${segment}/quote${suffix}`;
49:   }
50: 
51:   private readFromRouter(): RouteContext {
52:     const snapshot = this.router.routerState.snapshot.root;
53:     const path = this.router.url.split('?')[0];
54:     return {
55:       country: readCountryFromSnapshot(snapshot),
56:       step: path.includes('/summary') ? 'summary' : path.includes('/plans') ? 'plans' : 'policyholder',
57:     };
